import React, { useState } from 'react';
import { CAsyncSelect } from '@cloud-materials/common';
import type { DataSource } from '../interface';

export default () => {
  const [stateOne, _] = useState();
  const [stateTwo, setStateTwo] = useState();
  const [stateThree, setStateThree] = useState();
  const resultData: { label: string; value: string }[] = [];
  for (let i = 1; i <= 100; i++) {
    const label = `label${i}`;
    const value = `value${i}`;
    resultData.push({ label, value });
  }
  function getLoadMoreList(page: number, pageSize: number): Promise<DataSource> {
    const start = (page - 1) * pageSize;
    const end = page * pageSize;
    const list = resultData.slice(start, end);
    return new Promise(resolve => {
      setTimeout(() => {
        resolve({
          page,
          list,
          noMore: list.length < 10,
        });
      }, 500);
    });
  }

  return (
    <>
      <div>{'组件设计之初，组件默认受控非受控都由组件内部控制，本意是方便用户使用'}</div>
      <div>{'如下代码，传value但是没有传onChange，组件内部也会进行setState，保证效果'}</div>
      <CAsyncSelect value={stateOne} fetchData={({ page }) => getLoadMoreList(page, 10)} />
      <div>{'但是某些场景会收到约束'}</div>
      <div>{'比如使用者打算当选中的选项value是value1、value2或者value3的时候再setState'}</div>
      <div>{'这种就会有问题，因为组件内部会默认进行setState然后再调用外部传的onChange事件'}</div>
      <div>{'此时如果不进行处理，value不是value1、value2或者value3，也会进行setState'}</div>
      <CAsyncSelect
        value={stateTwo}
        fetchData={({ page }) => getLoadMoreList(page, 10)}
        onChange={val => {
          if (val === 'value1' || val === 'value2' || val === 'value3') {
            setStateTwo(val);
          }
        }}
      />
      <div>{'由于考虑到存量用户使用'}</div>
      <div>
        {'增加isControlStateChange参数，为true的时候，屏蔽默认的onChange的setState行为，state状态完全由用户控制'}
      </div>
      <div>{'这样处理之后就可以实现选项的value是value1、value2或者value3的时候再setState的效果'}</div>
      <CAsyncSelect
        value={stateThree}
        fetchData={({ page }) => getLoadMoreList(page, 10)}
        onChange={val => {
          if (val === 'value1' || val === 'value2' || val === 'value3') {
            setStateThree(val);
          }
        }}
        isControlStateChange
      />
    </>
  );
};

